                new InMemoryDirectoryServerConfig("dc=example,dc=com");
        cfg.addAdditionalBindCredentials("cn=admin,dc=example,dc=com", "adminpw");
        cfg.setListenerConfigs(InMemoryListenerConfig.createLDAPConfig(
