  before(async function() {
    apos = await t.create({
      root: module,
      modules: {
        // A restricted page type: only admins may edit/create pages of this type.
        'secret-page': {
          extend: '@apostrophecms/page-type',
          options: {
            editRole: 'admin',
            publishRole: 'admin'
          }
        },
